  'C',
  'Pilihan bernilai 5 adalah tindakan yang paling menunjukkan kompetensi antiradikalisme: mengarahkan diskusi pada fakta, penghormatan hak, dan penyelesaian damai. Pilihan bernilai 4 hanya menyelesaikan sebagian persoalan, sedangkan nilai 3, 2, dan 1 makin mengabaikan kebutuhan, koordinasi, atau prinsip pelayanan yang bertanggung jawab. Bobot ini merupakan simulasi pedagogis, bukan kunci resmi BKN. Strategi Akhir Latihan 1. Kelompokkan jawaban keliru berdasarkan submateri. 2. Untuk TIU, catat jenis kesalahan: hitung, salah baca, atau salah konsep. 3. Untuk TWK, telaah kembali prinsip dan penerapannya. 4. Untuk TKP, bandingkan kualitas tindakan dari semua opsi. 5. Ulangi latihan dengan batas waktu dan ukur peningkatan secara berkala. Rujukan pengembangan kisi-kisi KepmenPANRB No. 321 Tahun 2024 (ketentuan SKD CPNS TA 2024); sumber belajar sekunder: rekrutmencpns.id/materi, pejuangasn.com/kisi-kisi-cpns-2026, jadiasn.id/kisi-kisi-skd-cpns-2026/. Materi pada situs edukasi bukan sumber peraturan resmi. Pernyataan Hak Cipta Seluruh soal latihan pada paket ini disusun khusus untuk buku ini. Dilarang mengklaimnya sebagai soal resmi atau bocoran ujian. By HRT.',
